import unittest
from gateway import fetch
class Client:
    def __init__(self, response): self.response = response
    def get(self): return self.response
class IndependentTests(unittest.TestCase):
    def test_failure(self):
        with self.assertRaises(RuntimeError): fetch(Client({"status":503}))
    def test_success(self):
        self.assertEqual(fetch(Client({"status":200,"data":42})),42)

